import React, { useState, useEffect } from 'react';
import Papa from 'papaparse'; // make sure to run: npm install papaparse
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================

// 1. BACKEND CONNECTION
// Ensure this matches your Django server address
const BACKEND_URL = 'http://127.0.0.1:8000'; 
const PRESIGN_ENDPOINT = '/api/s3-presign'; // We will map this in urls.py later

// 2. FILE NAMES
// These must match exactly what is in your S3 bucket
const CSV_FILE_NAME = 'forecast_outputs.csv';
const TXT_FILE_NAME = 'lime_short_sentences.txt';

const RiverDashboard = () => {
    const [chartData, setChartData] = useState([]);
    const [limeSentences, setLimeSentences] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [lastUpdated, setLastUpdated] = useState(null);

    // ==========================================
    // DATA FETCHING LOGIC
    // ==========================================
    
    // Step 1: Ask Django for a temporary, secure S3 URL
    const getPresignedUrl = async (fileName) => {
        try {
            const response = await fetch(`${BACKEND_URL}${PRESIGN_ENDPOINT}?file=${fileName}`);
            if (!response.ok) {
                throw new Error(`Backend error: ${response.statusText}`);
            }
            const data = await response.json();
            return data.url; // This is the long AWS URL with signature
        } catch (err) {
            console.error(`Failed to sign URL for ${fileName}:`, err);
            return null;
        }
    };

    const fetchData = async () => {
        setLoading(true);
        setError(null);

        try {
            // 1. Get Signed URLs
            const csvUrl = await getPresignedUrl(CSV_FILE_NAME);
            const txtUrl = await getPresignedUrl(TXT_FILE_NAME);

            if (!csvUrl || !txtUrl) {
                throw new Error("Could not connect to AWS. Check Backend.");
            }

            // 2. Prepare Cache Buster
            // Since AWS updates the file hourly, we add a timestamp to force the browser 
            // to download the new version instead of using the cache.
            // Note: Presigned URLs already have '?', so we use '&'
            const timestamp = new Date().getTime();
            const bustCache = (url) => `${url}&t=${timestamp}`;

            // 3. Fetch and Parse CSV (Water Levels)
            const csvResponse = await fetch(bustCache(csvUrl));
            const csvText = await csvResponse.text();

            Papa.parse(csvText, {
                header: true,
                skipEmptyLines: true,
                complete: (results) => {
                    // Adapt this mapping to match your CSV headers exactly
                    const parsedData = results.data.map(row => ({
                        time: row.Timestamp, 
                        level: parseFloat(row.Predicted_Water_Level)
                    }));
                    setChartData(parsedData);
                },
            });

            // 4. Fetch and Parse Text (Explanations)
            const txtResponse = await fetch(bustCache(txtUrl));
            const txtData = await txtResponse.text();
            
            // Clean up the text data
            const lines = txtData.split('\n').filter(line => line.trim() !== '');
            setLimeSentences(lines);

            setLastUpdated(new Date().toLocaleTimeString());
            setLoading(false);

        } catch (err) {
            console.error("Error fetching live data:", err);
            setError("Failed to load real-time data from AWS.");
            setLoading(false);
        }
    };

    // Initial Load + Auto-Refresh Interval
    useEffect(() => {
        fetchData();

        // Refresh automatically every 10 minutes to catch the hourly update
        const intervalId = setInterval(fetchData, 600000); // 600,000 ms = 10 mins

        return () => clearInterval(intervalId);
    }, []);

    // ==========================================
    // RENDER
    // ==========================================
    return (
        <div className="dashboard-container">
            <h1 className="dashboard-title">River Water Level Forecast</h1>

            {/* Status Indicator */}
            <div className="status-bar" style={{ textAlign: 'center', marginBottom: '20px', color: '#555' }}>
                {loading && <span>⏳ Syncing with AWS S3...</span>}
                {error && <span style={{ color: 'red' }}>⚠️ {error}</span>}
                {!loading && !error && (
                    <span style={{ color: 'green', fontWeight: 'bold' }}>
                        ● Live Data (Last Sync: {lastUpdated})
                    </span>
                )}
            </div>

            <div className="dashboard-content">
                
                {/* Chart Section */}
                <div className="chart-card">
                    <h2>Forecast Trends</h2>
                    {chartData.length > 0 ? (
                        <div className="chart-placeholder">
                            {/* Insert your Recharts/ChartJS component here using {chartData} */}
                            <p>Displaying {chartData.length} hours of forecast data.</p>
                            <p>Next Predicted Level: <strong>{chartData[0]?.level} m</strong></p>
                        </div>
                    ) : (
                        <p>No forecast data available.</p>
                    )}
                </div>

                {/* Explanation Section */}
                <div className="lime-card">
                    <h2>AI Analysis</h2>
                    <div className="lime-list">
                        {limeSentences.map((line, index) => {
                            // Simple coloring logic
                            const isPositive = line.includes('increase'); 
                            const icon = isPositive ? '📈' : '📉';
                            
                            return (
                                <div key={index} className="lime-item">
                                    <span className="lime-icon">{icon}</span>
                                    <span>{line}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>

            </div>
            
            {/* Manual Refresh Button */}
            <button className="refresh-btn" onClick={fetchData}>
                🔄 Refresh
            </button>
        </div>
    );
};

export default RiverDashboard;
